class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def _send(self, obj, code=200):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(body)
    def _send_html(self, html, code=200):
        body = html.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)
    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        q = urllib.parse.parse_qs(parsed.query)
        path = parsed.path.rstrip("/")
        if path == "" or path == "/":
            self._send_html(PANEL_HTML)
            return
        if path == "/api/health":
            ok = os.path.exists(YTDLP)
            self._send({"ok": ok, "ytdlp": YTDLP, "exists": ok})
            return
        if path == "/api/version":
            code, out, err = run_ytdlp(["--version"], timeout=30)
            self._send({"ok": code == 0, "version": out.strip(), "error": err.strip()})
            return
        if path == "/api/info":
            url = q.get("url", [""])[0]
            if not url: self._send({"ok": False, "error": "missing url"}, 400); return
            self._send(do_info(url))
            return
        if path == "/api/play":
            url = q.get("url", [""])[0]
            fmt = q.get("format", ["best"])[0]
            if not url: self._send({"ok": False, "error": "missing url"}, 400); return
            self._send(do_play(url, fmt))
            return
        if path == "/api/download":
            url = q.get("url", [""])[0]
            fmt = q.get("format", ["best"])[0]
            if not url: self._send({"ok": False, "error": "missing url"}, 400); return
            self._send(do_download(url, fmt))
            return
        self._send({"ok": False, "error": "not found", "hint": "/api/health /api/version /api/info /api/play /api/download"}, 404)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--port", type=int, default=8898)
    ap.add_argument("--host", default="0.0.0.0")
    args = ap.parse_args()
    srv = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"yt-dlp API listening on {args.host}:{args.port}", flush=True)
    srv.serve_forever()

if __name__ == "__main__":
    main()
